/* ============================================================
   光华风洞·乘风者 —— 第一期灰盒原型（色块+文字，无美术）
   ============================================================ */

/* ------------------------------------------------------------
   ★ 手感参数表 —— 想调手感直接改这里的数字，其他都不用动 ★
   ------------------------------------------------------------ */
const PARAMS = {
  // —— 小球 ——
  gravity: 1400,        // 重力（下坠加速度），越大掉得越快
  inputAccel: 2600,     // 手指/按键横移的加速度
  maxVx: 480,           // 横向最大速度
  maxVy: 900,           // 普通状态的纵向速度上限
  columnMaxVy: 2200,    // 风柱内的速度上限（高得多=风柱是真加速，不是设定速度）
  vyDecay: 2.2,         // 出柱后超速速度的衰减速率（越大回落越快）
  dragX: 0.86,          // 横向空气阻力（每秒保留比例）

  // —— 阵风节奏 ——
  gustDur: 4.5,         // 狂风持续时间（秒）
  calmDur: 1.8,         // 滑翔期持续时间（秒）
  gustLift: 1700,       // 狂风期的上升托力（要 > gravity 才能升）
  calmDecel: 620,       // ★滑翔期固定减速度（物理式减速：冲多高滑多远，速度不锁死）
  glideMaxVx: 560,      // 滑翔期横向机动上限（比狂风期更灵活，方便入位下一根风柱）
  calmColumns: false,   // 滑翔期是否保留风洞（false=无风期风柱熄灭）

  // —— 超级加速：每过 5 根风柱触发，持续期间无风也持续托升 ——
  superEvery: 5,        // 每经过多少根风柱触发
  superDur: 3.2,        // 超级加速持续时间（秒）
  superLift: 940,       // 超级加速托力（滑翔期净余 ≈ +320/s，与狂风相当）

  // —— 受伤窗口：撞墙/被砸后进入带伤状态，期间再次受伤才出局 ——
  hurtWindow: 2.0,

  // —— 风柱（风洞缝隙） ——
  columnGap: 240,       // 相邻风柱的垂直间距（像素）
  columnWidth: 90,      // 风柱宽度
  columnCore: 34,       // 窄缝核心宽度（中心区域内升力翻倍）
  columnLift: 2600,     // 风柱升力
  columnCoreBonus: 2.0, // 核心区升力倍率
  turbulence: 1400,     // 风柱边缘乱流横推力

  // —— 涡流突变 ——
  vortexEveryMin: 6,    // 两次涡流的最小间隔（秒）
  vortexEveryMax: 12,   // 最大间隔（秒）
  vortexWarn: 0.8,      // 预警时间（秒）
  vortexForce: 2200,    // 涡流横推力
  vortexDur: 1.2,       // 涡流持续时间（秒）

  // —— 双塔（撞上即死） ——
  towerLeftW: 70,      // 左塔宽度（屏幕左侧）
  towerRightW: 70,     // 右塔宽度（屏幕右侧）
  canyonWobble: 60,    // 楼间缝隙宽度随高度的左右摆动幅度

  // —— 杂物（狂风期被甩上天的飞物，互相碰撞，撞墙反弹） ——
  debrisChance: 1,   // 每阵狂风生成杂物的概率
  debrisCount: 1,      // 每次生成几个
  debrisThrow: [250, 400],  // 出手初速比角色【当前】速度快多少
  debrisTilt: 0.45,    // 发射方向的倾斜上限（0=纯竖直，0.45=最多偏约24°）
  debrisSway: [40, 120], // 空中左右摇摆的幅度范围（湍流甩动感）
  debrisSpawn: [20, 80],  // 出生在屏幕外下方多远
  debrisGravity: 420,      // 狂风期杂物自身的轻重力（弧线弧度）
  debrisFallGravity: 1300, // 无风期杂物的下落加速度（要明显压过角色的滑翔速度）
  debrisBounce: 0.95,  // 撞墙反弹保留的水平速度比例

  // —— 视野缓冲 ——
  recoverRange: 380,    // 相机允许向下回溯的缓冲距离（保留之前的一小段楼层）

  // —— 换算与生成 ——
  pxPerMeter: 14,      // 多少像素算 1 米（142m≈光华楼顶）
  difficultyPerMeter: 0.004, // 难度随高度增长系数
  diffCap: 2.5,        // 难度系数上限（主要影响涡流频率）

  // —— 加速反馈 ——
  columnBoost: 280,    // 首次触碰风柱的瞬时助推（核心区×核心倍率）；每 5 根触发超级加速
  camZoomOut: 0.14,    // 高速上升时相机缩小的最大比例（视野变广=速度感）
  camLeadMax: 240,     // 高速时镜头向上多预留的视野（像素）
  zoomPunch: 0.06,     // 吃到风柱/狂风来临瞬间的镜头前冲量

  // —— 顺风（连击奖励，纯视觉+数值，无文字提示） ——
  comboBuffAt: 5,      // 连击达到该数量进入顺风
  comboLiftMult: 1.25, // 顺风期风柱升力倍率（柱芯变金色）

  // —— 难度纵深 ——
  canyonNarrowPerMeter: 0.06, // 峡谷每上升 1 米收窄量（半宽像素）
  canyonNarrowMax: 18,        // 收窄上限
  wobbleGrowPerMeter: 0.0027, // 峡谷摆动幅度增长系数
  wobbleGrowMax: 0.8,         // 摆动增幅上限（最多 ×1.8）
  debrisCountMax: 5,          // 每阵狂风杂物数量上限
  debrisEveryMeter: 150,      // 每上升多少米多 1 个杂物
};

/* ------------------------------------------------------------
   以下为游戏代码（一般不需要改）
   ------------------------------------------------------------ */
const LOGIC_W = 400, LOGIC_H = 720;
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

function resize() {
  const scale = Math.min(innerWidth / LOGIC_W, innerHeight / LOGIC_H);
  canvas.width = LOGIC_W * window.devicePixelRatio;
  canvas.height = LOGIC_H * window.devicePixelRatio;
  canvas.style.width = (LOGIC_W * scale) + 'px';
  canvas.style.height = (LOGIC_H * scale) + 'px';
  ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);
}
addEventListener('resize', resize);
resize();

// —— 输入 ——
const input = { left: false, right: false };
addEventListener('keydown', (e) => {
  initAudio();
  if (e.key === 'm' || e.key === 'M') toggleMute();
  if (e.key === 'ArrowLeft') input.left = true;
  if (e.key === 'ArrowRight') input.right = true;
  if (e.key === ' ' || e.key === 'Enter') advanceState();
});
addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft') input.left = false;
  if (e.key === 'ArrowRight') input.right = false;
});
function touchPos(e) {
  const rect = canvas.getBoundingClientRect();
  const t = e.touches[0] || e.changedTouches[0];
  return { p: (t.clientX - rect.left) / rect.width, q: (t.clientY - rect.top) / rect.height };
}
canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  initAudio();
  const pos = touchPos(e);
  if (pos.p > 0.86 && pos.q < 0.1) { toggleMute(); return; } // 右上角静音钮
  if (state !== 'playing') { advanceState(); return; }
  if (pos.p < 0.5) input.left = true; else input.right = true;
}, { passive: false });
canvas.addEventListener('touchend', (e) => {
  e.preventDefault();
  input.left = input.right = false;
}, { passive: false });
canvas.addEventListener('mousedown', (e) => {
  initAudio();
  const rect = canvas.getBoundingClientRect();
  const p = (e.clientX - rect.left) / rect.width;
  const q = (e.clientY - rect.top) / rect.height;
  if (p > 0.86 && q < 0.1) { toggleMute(); return; } // 右上角静音钮
  if (state !== 'playing') { advanceState(); return; }
  if (p < 0.5) input.left = true; else input.right = true;
});
canvas.addEventListener('mouseup', () => { input.left = input.right = false; });

// —— 世界几何 ——
// 双塔固定在左右两侧，中间是楼间缝隙（峡谷）；缝隙中心随高度轻微摆动，
// 且越往上缝隙越窄、摆动越大（难度纵深）；墙缘保证不出屏
function canyonHalfAt(worldY) {
  const meters = Math.max(0, -worldY / PARAMS.pxPerMeter);
  const narrow = Math.min(PARAMS.canyonNarrowMax, meters * PARAMS.canyonNarrowPerMeter);
  return (LOGIC_W - PARAMS.towerLeftW - PARAMS.towerRightW) / 2 - 10 - narrow;
}
function canyonCenterAt(worldY) {
  const meters = Math.max(0, -worldY / PARAMS.pxPerMeter);
  let amp = PARAMS.canyonWobble * (1 + Math.min(PARAMS.wobbleGrowMax, meters * PARAMS.wobbleGrowPerMeter));
  amp = Math.min(amp, Math.max(0, 198 - canyonHalfAt(worldY))); // 摆动过大时收着点，别让墙缘滑出屏幕
  const wobble = Math.sin(worldY * 0.0016) * amp;
  return LOGIC_W / 2 + wobble;
}

// —— 校徽贴图（assets/fudan.png 已离线处理好：裁剪+白底透明；失败则用手绘版兜底） ——
const FUDAN_B64 = '';
const fudanImg = new Image();
let fudanImgReady = false;
fudanImg.onload = () => { fudanImgReady = true; };
fudanImg.onerror = () => { fudanImgReady = false; };
fudanImg.src = 'data:image/png;base64,' + FUDAN_B64;

// —— 本地存储（受限环境下不崩） ——
function lsGet(k, d) { try { const v = localStorage.getItem(k); return v === null ? d : v; } catch { return d; } }
function lsSet(k, v) { try { localStorage.setItem(k, String(v)); } catch {} }

// —— 程序化音效（WebAudio 零素材；首次点击/按键激活；M 键或右上角喇叭静音） ——
let audio = null, muted = lsGet('ghfd_mute', 0) == 1;
let windGain = null, windFilter = null;
function initAudio() {
  if (muted) return;
  if (!audio) {
    try { audio = new (window.AudioContext || window.webkitAudioContext)(); } catch { return; }
    const len = audio.sampleRate * 2, buf = audio.createBuffer(1, len, audio.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    const src = audio.createBufferSource(); src.buffer = buf; src.loop = true;
    windFilter = audio.createBiquadFilter(); windFilter.type = 'lowpass'; windFilter.frequency.value = 350;
    windGain = audio.createGain(); windGain.gain.value = 0.0001;
    src.connect(windFilter); windFilter.connect(windGain); windGain.connect(audio.destination);
    src.start();
  }
  if (audio.state === 'suspended') audio.resume();
}
function tone(freq, dur, type, vol, slideTo) {
  if (!audio || muted) return;
  const t0 = audio.currentTime;
  const o = audio.createOscillator(), g = audio.createGain();
  o.type = type || 'sine';
  o.frequency.setValueAtTime(freq, t0);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(30, slideTo), t0 + dur);
  g.gain.setValueAtTime(vol || 0.15, t0);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  o.connect(g); g.connect(audio.destination);
  o.start(t0); o.stop(t0 + dur + 0.02);
}
function whoosh(dur, f0, f1, vol) {
  if (!audio || muted) return;
  const t0 = audio.currentTime;
  const len = Math.max(1, Math.ceil(audio.sampleRate * dur)), buf = audio.createBuffer(1, len, audio.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = audio.createBufferSource(); src.buffer = buf;
  const bp = audio.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 1.1;
  bp.frequency.setValueAtTime(f0, t0);
  bp.frequency.exponentialRampToValueAtTime(Math.max(30, f1), t0 + dur);
  const g = audio.createGain(); g.gain.value = vol || 0.22;
  src.connect(bp); bp.connect(g); g.connect(audio.destination);
  src.start(t0);
}
function sfx(kind) {
  if (!audio || muted) return;
  switch (kind) {
    case 'boost':  whoosh(0.28, 500, 2400, 0.2); tone(330, 0.15, 'triangle', 0.11, 660); break;
    case 'core':   whoosh(0.32, 600, 3200, 0.24); tone(523, 0.18, 'triangle', 0.13, 1046); break;
    case 'super':  [392, 523, 659, 784, 1046].forEach((f, i) => setTimeout(() => tone(f, 0.16, 'triangle', 0.15), i * 70));
                   whoosh(0.6, 300, 2600, 0.22); break;
    case 'gust':   whoosh(0.5, 200, 900, 0.1); break;
    case 'bounce': tone(170, 0.12, 'square', 0.1, 85); whoosh(0.12, 1200, 320, 0.14); break;
    case 'hit':    tone(140, 0.16, 'square', 0.11, 70); whoosh(0.15, 900, 220, 0.22); break;
    case 'warn':   tone(660, 0.09, 'square', 0.06); setTimeout(() => tone(660, 0.09, 'square', 0.06), 150); break;
    case 'die':    tone(300, 0.55, 'sawtooth', 0.11, 60); whoosh(0.5, 800, 120, 0.16); break;
    case 'record': [523, 659, 784, 1046].forEach((f, i) => setTimeout(() => tone(f, 0.2, 'triangle', 0.15), i * 130)); break;
  }
}
function toggleMute() {
  muted = !muted;
  lsSet('ghfd_mute', muted ? 1 : 0);
  if (muted) { if (windGain) windGain.gain.setTargetAtTime(0.0001, audio.currentTime, 0.08); }
  else initAudio();
}

// —— 状态 ——
let state = 'menu'; // menu | playing | dying | over
let ball, columns, debrisList, particles;
let camY, gameT, gustT, gustPhase, vortex, vortexTimer, combo, comboTimer, comboPop, maxMeters, bestMeters;
let deathReason = '';
let shakeT = 0, shakeAmp = 0; // 受击屏幕震动
let zoomCur = 1, zoomPunchT = 0; // 相机缩放（速度感）与入柱前冲
let colCount = 0, superT = 0, hurtT = 0; // 累计过柱数 / 超级加速剩余 / 受伤窗口
bestMeters = +(lsGet('ghfd_best', 0));

function reset() {
  ball = { x: LOGIC_W / 2, y: -160, vx: 0, vy: 0, svy: 0, py: -160, r: 16, bounces: 0, hitFlash: 0 };
  zoomCur = 1; zoomPunchT = 0;
  colCount = 0; superT = 0; hurtT = 0;
  camY = -LOGIC_H * 0.7;
  gameT = 0; gustT = 0; gustPhase = 'gust'; // 开局就是狂风，把玩家托起来
  vortex = null; vortexTimer = rand(PARAMS.vortexEveryMin, PARAMS.vortexEveryMax);
  combo = 0; comboTimer = 0; comboPop = 0; maxMeters = 0;
  columns = []; debrisList = []; particles = [];
  genColumnsUpTo(camY - 1200);
}

function rand(a, b) { return a + Math.random() * (b - a); }
function nowT() { return performance.now() / 1000; } // 墙钟时间：菜单动画/天空氛围用，不受游戏暂停影响

/* ---------- 手绘涂鸦辅助 ---------- */
// 由整数坐标决定的伪随机（同一线条每帧抖动一致，不闪烁）
function srand(seed) {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}
// 手绘线：两端点各带一点抖动，中间再折一折
function dLine(x1, y1, x2, y2, seed = 0, w = 2) {
  const j1 = (srand(seed) - 0.5) * 3, j2 = (srand(seed + 1) - 0.5) * 3;
  const mx = (x1 + x2) / 2 + (srand(seed + 2) - 0.5) * 4;
  const my = (y1 + y2) / 2 + (srand(seed + 3) - 0.5) * 4;
  ctx.lineWidth = w;
  ctx.beginPath();
  ctx.moveTo(x1 + j1, y1 + j1);
  ctx.lineTo(mx, my);
  ctx.lineTo(x2 + j2, y2 + j2);
  ctx.stroke();
}
// 手绘矩形：四条歪线
function dRect(x, y, w, h, seed = 0, lw = 2) {
  dLine(x, y, x + w, y, seed, lw);
  dLine(x + w, y, x + w, y + h, seed + 10, lw);
  dLine(x + w, y + h, x, y + h, seed + 20, lw);
  dLine(x, y + h, x, y, seed + 30, lw);
}
// 手绘圆：不闭合的歪圆（起终点留个小缺口）
function dCircle(cx, cy, r, seed = 0, lw = 2) {
  ctx.lineWidth = lw;
  ctx.beginPath();
  const start = srand(seed) * Math.PI * 2;
  const end = start + Math.PI * 1.85; // 留缺口
  ctx.moveTo(cx + Math.cos(start) * r, cy + Math.sin(start) * r);
  for (let a = start; a <= end; a += 0.35) {
    const rr = r * (1 + (srand(seed + a * 10 | 0) - 0.5) * 0.08);
    ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr);
  }
  ctx.stroke();
}
// 排线阴影（涂鸦打阴影的斜线）
function hatch(x, y, w, h, seed = 0, gap = 7, lw = 1) {
  ctx.lineWidth = lw;
  for (let i = 0; i * gap < w + h; i += 1) {
    const sx = x + Math.min(i * gap, w), sy = y + Math.max(0, i * gap - w);
    const ex = x + Math.max(0, i * gap - h), ey = y + Math.min(i * gap, h);
    dLine(sx, sy, ex, ey, seed + i * 7, lw);
  }
}

function genColumnsUpTo(topY) {
  // 风柱左右交替，从地面向上铺到 topY
  let side = columns.length % 2 === 0 ? 1 : -1;
  let nextY = columns.length ? columns[columns.length - 1].y - PARAMS.columnGap : -140;
  while (nextY > topY) {
    const center = canyonCenterAt(nextY) + rand(-canyonHalfAt(nextY) * 0.55, canyonHalfAt(nextY) * 0.55);
    columns.push({ y: nextY, x: center, side });
    side = -side;
    nextY -= PARAMS.columnGap * rand(0.85, 1.2);
  }
}

function advanceState() {
  if (state === 'menu') { reset(); state = 'playing'; }
  else if (state === 'over') { state = 'menu'; }
}

function die(reason) {
  if (state !== 'playing') return;
  deathReason = reason;
  state = 'dying';
  ball.deathT = 0;
  sfx('die');
}

function metersOf(y) { return Math.max(0, Math.round(-y / PARAMS.pxPerMeter)); }

function landmark(m) {
  if (m < 15) return '还在邯郸路上空…';
  if (m < 40) return '超过了路边梧桐树梢';
  if (m < 80) return '超过了辰光超市天花板';
  if (m < 120) return '超过了文科图书馆';
  if (m < 142) return '即将抵达光华楼顶！';
  if (m < 200) return '已超越光华楼顶，师大遥遥相望';
  if (m < 300) return '进入复旦对流层';
  return '欢迎来到复旦平流层 🧑‍🚀';
}
function titleOf(m) {
  if (m < 20) return '落叶级选手 🍂';
  if (m < 60) return '伞面翻转变形者 ☂️';
  if (m < 100) return '外卖保卫者 🛵';
  if (m < 150) return '光华楼常驻居民 🏢';
  if (m < 250) return '风系大法师 🌪️';
  if (m < 400) return '邯郸路气象台荣誉台长 📡';
  return '复旦平流层守门人 🧑‍🚀';
}

// —— 更新 ——
function update(dt) {
  if (state === 'menu' || state === 'over') return;

  if (state === 'dying') {
    // 坠地弹两下（喜剧效果）：小球继续物理运动到地面
    if (shakeT > 0) shakeT -= dt;
    // 死亡镜头：缓缓跟随小球坠落，让落地弹跳发生在画面内
    camY += ((ball.y - LOGIC_H * 0.42) - camY) * Math.min(1, dt * 5);
    if (ball.y > camY + LOGIC_H - 70) camY = ball.y - (LOGIC_H - 70); // 保底：再快的坠落也不出画
    zoomCur += (1 - zoomCur) * Math.min(1, dt * 3); zoomPunchT = 0; // 死亡时视野缓缓回正
    ball.deathT += dt;
    ball.vy += PARAMS.gravity * dt;
    ball.x += ball.vx * dt;
    ball.y += ball.vy * dt;
    if (ball.y >= -ball.r - 4) {
      ball.y = -ball.r - 4;
      if (Math.abs(ball.vy) > 120 && ball.bounces < 2) {
        ball.vy = -ball.vy * 0.45; ball.vx *= 0.6; ball.bounces++;
      } else if (ball.deathT > 1.2) {
        if (maxMeters > bestMeters) { bestMeters = maxMeters; lsSet('ghfd_best', bestMeters); sfx('record'); }
        state = 'over';
      }
    }
    if (ball.deathT > 2.5) {
      if (maxMeters > bestMeters) { bestMeters = maxMeters; localStorage.setItem('ghfd_best', bestMeters); }
      state = 'over';
    }
    return;
  }

  gameT += dt;
  const prevVy = ball.vy, prevVx = ball.vx; // 记录真实加速度（供杂物同步 & 小球倾斜）
  const diff = 1 + Math.min(PARAMS.diffCap, maxMeters * PARAMS.difficultyPerMeter);

  // 阵风节奏
  gustT += dt;
  if (gustPhase === 'calm' && gustT >= PARAMS.calmDur) { gustPhase = 'gust'; gustT = 0; zoomPunchT = Math.max(zoomPunchT, 0.035); sfx('gust'); onGustStart(); }
  else if (gustPhase === 'gust' && gustT >= PARAMS.gustDur / Math.min(1.15, diff)) { gustPhase = 'calm'; gustT = 0; } // 难度最多只缩短15%
  const gusting = gustPhase === 'gust';

  // 涡流
  if (vortex) {
    vortex.t += dt;
    if (vortex.t > vortex.warn + PARAMS.vortexDur) vortex = null;
  } else {
    vortexTimer -= dt;
    if (vortexTimer <= 0) {
      vortex = { t: 0, warn: PARAMS.vortexWarn, dir: Math.random() < 0.5 ? -1 : 1 };
      vortexTimer = rand(PARAMS.vortexEveryMin, PARAMS.vortexEveryMax) / diff;
      sfx('warn');
    }
  }

  if (ball.hitFlash > 0) ball.hitFlash -= dt;
  if (shakeT > 0) shakeT -= dt;
  if (superT > 0) {
    superT -= dt;
    if (superT > 0 && Math.random() < 0.6) { // 超级加速的金色尾迹
      particles.push({ x: ball.x + rand(-8, 8), y: ball.y + ball.r, vx: rand(-30, 30), vy: rand(80, 200), life: 0.45, gold: true });
    }
  }
  if (hurtT > 0) hurtT -= dt;

  // 横向输入
  if (input.left) ball.vx -= PARAMS.inputAccel * dt;
  if (input.right) ball.vx += PARAMS.inputAccel * dt;

  // 纵向力：狂风期 = 重力 vs 风的托力；滑翔期 = 固定减速度（物理式，冲多高滑多远）；
  // 超级加速期间无风也持续托升
  if (gusting) {
    ball.vy += PARAMS.gravity * dt;
    ball.vy -= PARAMS.gustLift * dt;
  } else {
    ball.vy += PARAMS.calmDecel * dt;
    if (superT > 0) ball.vy -= PARAMS.superLift * dt;
  }

  // 风柱（平静期风洞失效，只剩狂风期喷发）；顺风（连击≥阈值）时升力提升、视觉变金
  let inColumn = false, inCore = false;
  const buffed = combo >= PARAMS.comboBuffAt;
  const liftNow = PARAMS.columnLift * (buffed ? PARAMS.comboLiftMult : 1);
  for (const c of columns) {
    if (!gusting && !PARAMS.calmColumns) break;
    const withinX = Math.abs(ball.x - c.x) < PARAMS.columnWidth / 2;
    const inBand = Math.abs(ball.y - c.y) < 8 + ball.r;
    const crossedUp = (ball.py ?? ball.y) >= c.y && ball.y <= c.y; // 扫掠判定：高速上行也不会整帧穿透
    if (withinX && (inBand || crossedUp)) {
      inColumn = true;
      const off = (ball.x - c.x) / (PARAMS.columnWidth / 2); // -1..1
      if (Math.abs(ball.x - c.x) < PARAMS.columnCore / 2) {
        inCore = true;
        ball.vy -= liftNow * PARAMS.columnCoreBonus * dt;
      } else {
        ball.vy -= liftNow * dt;
        // 缝隙边缘乱流横推
        ball.vx += Math.sign(off || 1) * PARAMS.turbulence * dt;
      }
      if (!c.touched) {
        c.touched = true; combo++; comboTimer = 3; comboPop = 0.35;
        // 瞬时助推（帧率无关的“澎”一下）+ 镜头前冲
        ball.vy -= PARAMS.columnBoost * (inCore ? PARAMS.columnCoreBonus : 1);
        zoomPunchT = PARAMS.zoomPunch;
        // 超级加速：每过 5 根必触发，持续期间无风也托升
        colCount++;
        if (colCount % PARAMS.superEvery === 0) {
          superT = PARAMS.superDur;
          zoomPunchT = PARAMS.zoomPunch * 1.8;
          sfx('super');
          for (let pi = 0; pi < 16; pi++) {
            const pa = rand(0, Math.PI * 2);
            particles.push({ x: ball.x + Math.cos(pa) * 12, y: ball.y + Math.sin(pa) * 10, vx: Math.cos(pa) * 190, vy: Math.sin(pa) * 190 - 80, life: 0.7, gold: true });
          }
        } else {
          sfx(inCore ? 'core' : 'boost');
        }
        for (let pi = 0; pi < 8; pi++) {
          const pa = rand(0, Math.PI * 2);
          particles.push({ x: ball.x + Math.cos(pa) * 10, y: ball.y + Math.sin(pa) * 8, vx: Math.cos(pa) * 130, vy: -rand(160, 430), life: 0.5, green: true, gold: buffed || superT > 0 });
        }
      }
    }
  }
  comboTimer -= dt;
  if (comboTimer <= 0) combo = 0;
  ball.inColumn = inColumn; ball.inCore = inCore; ball.gusting = gusting; // 供渲染做加速反馈
  // 风柱加速反馈：喷气流粒子
  if (inColumn && Math.random() < 0.7) {
    particles.push({ x: ball.x + rand(-ball.r, ball.r), y: ball.y + ball.r, vy: -rand(350, 650), life: 0.6, green: true });
  }

  // 涡流横推（预警后生效）
  if (vortex && vortex.t > vortex.warn) {
    ball.vx += vortex.dir * PARAMS.vortexForce * dt;
  }

  // 阻力 & 限速（滑翔期横移上限更高：调整入位的时间窗口）
  ball.vx *= Math.pow(PARAMS.dragX, dt * 60);
  const vxMax = gusting ? PARAMS.maxVx : PARAMS.glideMaxVx;
  ball.vx = clamp(ball.vx, -vxMax, vxMax);
  // 纵向：柱内允许冲到高上限（真加速）；出柱后超速不再硬夹断，
  // 而是按 vyDecay 平滑衰减回普通上限——助推的余速保留下来，才有“弹射”的手感
  const capNow = inColumn ? PARAMS.columnMaxVy : PARAMS.maxVy;
  if (inColumn) {
    if (ball.vy < -capNow) ball.vy = -capNow;
  } else if (ball.vy < -PARAMS.maxVy) {
    ball.vy += PARAMS.columnMaxVy * PARAMS.vyDecay * dt;
    if (ball.vy > -PARAMS.maxVy) ball.vy = -PARAMS.maxVy;
  }
  ball.py = ball.y; // 上一帧位置（供风柱扫掠判定）
  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;
  ball.ay = (ball.vy - prevVy) / dt; // 本帧真实纵向加速度（含风柱加成）
  ball.ax = (ball.vx - prevVx) / dt; // 本帧真实横向加速度（供倾斜）
  ball.svy = (ball.svy ?? ball.vy) + (ball.vy - ball.svy) * Math.min(1, dt * 6); // 平滑速度（驱动相机/拉伸）

  // 撞塔判定：物理反弹；带伤状态下再撞才出局（否则进入 2 秒受伤窗口，红闪提示）
  const cc = canyonCenterAt(ball.y), half = canyonHalfAt(ball.y);
  if (ball.x - ball.r < cc - half || ball.x + ball.r > cc + half) {
    ball.x = clamp(ball.x, cc - half + ball.r + 1, cc + half - ball.r - 1);
    ball.vx = -ball.vx * 0.65; // 回弹并损失部分动能
    ball.vy *= 0.92;
    if (hurtT > 0) { die('连续撞上了光华楼墙 🧱'); return; }
    hurtT = PARAMS.hurtWindow;
    shakeT = 0.25; shakeAmp = 5;
    sfx('bounce');
    for (let pi = 0; pi < 8; pi++) {
      const pa = rand(0, Math.PI * 2);
      particles.push({ x: ball.x, y: ball.y, vx: Math.cos(pa) * 130, vy: Math.sin(pa) * 130, life: 0.45 });
    }
  }

  // 坠地判定
  if (ball.y >= -ball.r) { ball.bounces = 0; die('掉回草坪了 🌱'); return; }

  // 杂物：纯抛物线（只有重力），发射初速度已算好让它恰好越过角色头顶
  for (let i = debrisList.length - 1; i >= 0; i--) {
    const d = debrisList[i];
    // 狂风期：复制角色的实时真实加速度 ball.ay（含风柱加成）→ 相对速度永远≈出手差值，一定追得上
    // 平静期：只受自身轻重力，加速落下（角色在滑翔）→ 从头顶掉下来
    const ay = gusting ? (ball.ay ?? (PARAMS.gustLift - PARAMS.gravity)) : PARAMS.debrisFallGravity;
    d.vy += ay * dt;
    // 横向 = 发射初速 + 湍流摇摆（纸片感）
    d.x += (d.vx + Math.sin(gameT * d.swayFreq + d.swayPhase) * d.swayAmp) * dt;
    d.y += d.vy * dt;
    d.rot += d.spin * dt;
    d.trail.push({ x: d.x, y: d.y });
    if (d.trail.length > 10) d.trail.shift();
    // 撞到楼缝两壁反弹：只翻转水平速度，竖直速度不变
    const cc2 = canyonCenterAt(d.y), h2 = canyonHalfAt(d.y);
    if (d.x < cc2 - h2 + d.w / 2) { d.x = cc2 - h2 + d.w / 2; d.vx = Math.abs(d.vx) * PARAMS.debrisBounce; }
    if (d.x > cc2 + h2 - d.w / 2) { d.x = cc2 + h2 - d.w / 2; d.vx = -Math.abs(d.vx) * PARAMS.debrisBounce; }
    // 飞出视野太远就清理
    if (d.y > camY + LOGIC_H + 500 || d.y < camY - 2500) { debrisList.splice(i, 1); continue; }
    if (Math.abs(d.x - ball.x) < d.w / 2 + ball.r * 0.8 && Math.abs(d.y - ball.y) < d.h / 2 + ball.r * 0.8) {
      // 伤未愈再被砸 = 出局；否则进入受伤窗口
      if (hurtT > 0) { die('伤上加伤，被杂物砸中 💥'); return; }
      hurtT = PARAMS.hurtWindow;
      // 砸中不直接死：物理碰撞——球重(3)杂物轻(1)，互相弹开，球被撞飞并眩晕
      const dx = ball.x - d.x, dy = ball.y - d.y;
      const dist = Math.hypot(dx, dy) || 1;
      const nx = dx / dist, ny = dy / dist;
      const minDist = ball.r + d.w / 2;
      const overlap = minDist - Math.min(dist, minDist);
      ball.x += nx * overlap * 0.25; ball.y += ny * overlap * 0.25;
      d.x -= nx * overlap * 0.75; d.y -= ny * overlap * 0.75;
      // 沿法线的相对速度 → 冲量（动量守恒，M=2, m=1，弹性系数1.4=撞击很弹）
      const rvn = (ball.vx - d.vx) * nx + (ball.vy - d.vy) * ny;
      if (rvn < 0) {
        const j = -(1 + 1.4) * rvn / (1 / 2 + 1);
        ball.vx += (j / 2) * nx; ball.vy += (j / 2) * ny;
        d.vx -= j * nx; d.vy -= j * ny;
      }
      combo = 0;
      ball.hitFlash = 0.3;              // 红闪提示
      shakeT = 0.25; shakeAmp = 4;      // 屏幕轻震（幅度随时间衰减）
      sfx('hit');
    }
  }

  // 杂物间碰撞：等质量弹性碰撞（沿连线方向交换速度分量），并把重叠推开
  for (let i = 0; i < debrisList.length; i++) {
    for (let j = i + 1; j < debrisList.length; j++) {
      const a = debrisList[i], b = debrisList[j];
      const dx = b.x - a.x, dy = b.y - a.y;
      const dist = Math.hypot(dx, dy), minDist = (a.w + b.w) / 2;
      if (dist > 0 && dist < minDist) {
        const nx = dx / dist, ny = dy / dist; // 碰撞法线
        // 分离重叠
        const overlap = (minDist - dist) / 2;
        a.x -= nx * overlap; a.y -= ny * overlap;
        b.x += nx * overlap; b.y += ny * overlap;
        // 沿法线交换速度分量（等质量弹性碰撞）
        const va = a.vx * nx + a.vy * ny;
        const vb = b.vx * nx + b.vy * ny;
        if (va - vb > 0) { // 只在互相接近时才碰撞
          a.vx += (vb - va) * nx; a.vy += (vb - va) * ny;
          b.vx += (va - vb) * nx; b.vy += (va - vb) * ny;
        }
      }
    }
  }

  // 相机跟随：向上紧跟，向下只能回溯一小段缓冲（保留之前的楼层）
  // 速度越快镜头越往上探（前瞻），配合缩放制造速度感
  ball.peakY = Math.min(ball.peakY ?? ball.y, ball.y); // 记录到达过的最高点
  const lead = Math.min(PARAMS.camLeadMax, Math.max(0, -(ball.svy ?? ball.vy) - 500) * 0.4);
  const targetTop = ball.y - LOGIC_H * 0.42 - lead;
  const camFloor = (ball.peakY - LOGIC_H * 0.42) + PARAMS.recoverRange; // 相机最多退到这里
  const clamped = Math.min(targetTop, camFloor);
  camY += (clamped - camY) * Math.min(1, dt * 8);

  // 彻底掉出屏幕底部 → 失败
  if (ball.y > camY + LOGIC_H + ball.r) { ball.bounces = 0; die('被风抛弃，坠出视野 🕳️'); return; }

  // 风柱生成与清理
  genColumnsUpTo(camY - 1200);
  columns = columns.filter((c) => c.y < camY + LOGIC_H + 300);
  maxMeters = Math.max(maxMeters, metersOf(ball.y));

  // 风粒子
  if (gusting && Math.random() < 0.5) {
    particles.push({ x: rand(0, LOGIC_W), y: camY - 20, vy: rand(200, 420), life: 1 });
  } else if (!gusting && Math.random() < 0.3) {
    // 滑翔期：细小的下行气流线，衬托缓缓上飘的相对运动
    particles.push({ x: ball.x + rand(-90, 90), y: ball.y + rand(-60, 120), vy: rand(140, 260), life: 0.5 });
  }
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.y += p.vy * dt; p.x += (p.vx || 0) * dt; p.life -= dt * 1.2;
    if (p.life <= 0) particles.splice(i, 1);
  }

  // 相机缩放：500px/s 起效、1700px/s 拉满，视野随速度明显撑开；zoomPunchT 提供吃柱瞬间的“前冲-回弹”
  zoomPunchT = Math.max(0, zoomPunchT - zoomPunchT * 7 * dt);
  const zT = 1 - Math.min(PARAMS.camZoomOut, Math.max(0, -(ball.svy ?? ball.vy) - 500) / 1200 * PARAMS.camZoomOut) + zoomPunchT;
  zoomCur += (zT - zoomCur) * Math.min(1, dt * 5);

  // 风声随速度与风相起伏
  if (windGain) {
    const spd = Math.max(0, -(ball.svy ?? ball.vy));
    const wTarget = muted ? 0.0001 : 0.018 + Math.min(0.07, spd / 2200 * 0.07) + (gusting ? 0.03 : 0) + (ball.inColumn ? 0.02 : 0);
    windGain.gain.setTargetAtTime(wTarget, audio.currentTime, 0.25);
    windFilter.frequency.setTargetAtTime(260 + Math.min(1300, spd * 0.5), audio.currentTime, 0.25);
  }
}

function onGustStart() {
  if (Math.random() < PARAMS.debrisChance) {
    const kinds = ['umbrella', 'takeout', 'paper', 'bike', 'book'];
    const n = Math.min(PARAMS.debrisCountMax, PARAMS.debrisCount + Math.floor(maxMeters / PARAMS.debrisEveryMeter)); // 越高杂物越多
    for (let i = 0; i < n; i++) {
      const kind = kinds[Math.floor(Math.random() * kinds.length)];
      const y = camY + LOGIC_H + rand(PARAMS.debrisSpawn[0], PARAMS.debrisSpawn[1]); // 屏幕外下方
      // 初速 = 角色当前速度 + 出手力度；狂风期杂物与角色受相同托力，所以相对稳定可见
      const speed = -(ball.vy - rand(PARAMS.debrisThrow[0], PARAMS.debrisThrow[1]));
      const tilt = rand(-PARAMS.debrisTilt, PARAMS.debrisTilt); // 水平分量占比
      const h = canyonHalfAt(y);
      debrisList.push({
        x: canyonCenterAt(y) + rand(-h * 0.7, h * 0.7),
        y, w: 34, h: 34,
        vx: speed * tilt,
        vy: -Math.sqrt(Math.max(0, speed * speed * (1 - tilt * tilt))),
        spin: rand(-2, 2), rot: 0, trail: [],
        swayAmp: rand(PARAMS.debrisSway[0], PARAMS.debrisSway[1]),
        swayFreq: rand(1.5, 3), swayPhase: rand(0, Math.PI * 2),
        kind, seed: Math.floor(rand(0, 9999)),
      });
    }
  }
}

// 手绘杂物（涂鸦简笔画）：以杂物中心为原点、约 ±16px 大小
function drawDebrisDoodle(kind, seed) {
  ctx.strokeStyle = '#2d3748';
  switch (kind) {
    case 'umbrella': { // 雨伞：弧形伞面 + 伞骨 + 弯把
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(0, 4, 15, Math.PI, Math.PI * 2); ctx.stroke(); // 伞面弧
      dLine(-15, 4, 0, -11, seed, 1.5); dLine(0, -11, 15, 4, seed + 1, 1.5); // 伞顶折线
      dLine(-8, 4, -6, 8, seed + 2, 1.2); dLine(0, 4, 0, 8, seed + 3, 1.2); dLine(8, 4, 6, 8, seed + 4, 1.2); // 伞骨
      ctx.beginPath(); ctx.arc(1.5, 13, 3, -Math.PI / 2, Math.PI / 2); ctx.stroke(); // 弯把
      dLine(0, -11, 0, 11, seed + 5, 2); // 伞杆
      break;
    }
    case 'takeout': { // 外卖盒：方盒 + 盒盖 + 一双筷子
      ctx.fillStyle = '#fff8e7';
      ctx.fillRect(-14, -6, 28, 18);
      dRect(-14, -6, 28, 18, seed, 2);
      dLine(-14, -6, -10, -13, seed + 1, 1.5); dLine(14, -6, 10, -13, seed + 2, 1.5);
      dLine(-10, -13, 10, -13, seed + 3, 1.5); // 盒盖
      dLine(-3, -13, -5, -26, seed + 4, 1.5); dLine(3, -13, 5, -26, seed + 5, 1.5); // 筷子
      break;
    }
    case 'paper': { // 试卷：一张纸 + 乱写的答题线 + 大叉
      ctx.fillStyle = '#fffdf5';
      ctx.fillRect(-12, -15, 24, 30);
      dRect(-12, -15, 24, 30, seed, 1.8);
      ctx.lineWidth = 1;
      dLine(-8, -8, 8, -9, seed + 1, 1); dLine(-8, -2, 8, -3, seed + 2, 1);
      dLine(-8, 4, 8, 3, seed + 3, 1);
      ctx.lineWidth = 1.8; // 红叉（没及格）
      dLine(-6, 7, 6, 13, seed + 4, 1.8); dLine(6, 7, -6, 13, seed + 5, 1.8);
      break;
    }
    case 'bike': { // 自行车：两个歪轮 + 车架 + 车把
      dCircle(-10, 8, 8, seed, 1.8);
      dCircle(10, 8, 8, seed + 1, 1.8);
      dLine(-10, 8, -2, -6, seed + 2, 1.8); dLine(-2, -6, 10, 8, seed + 3, 1.8);
      dLine(-2, -6, 3, -7, seed + 4, 1.8); dLine(3, -7, 7, -12, seed + 5, 1.8); // 车把
      dLine(-2, -6, -4, -12, seed + 6, 1.5); // 座椅杆
      dLine(-7, -12, -1, -13, seed + 7, 2); // 座椅
      break;
    }
    case 'book': { // 论文书：厚书 + 书脊 + 书名线
      ctx.fillStyle = '#f0e6d2';
      ctx.fillRect(-13, -11, 26, 22);
      dRect(-13, -11, 26, 22, seed, 2);
      dLine(-8, -11, -8, 11, seed + 1, 1.8); // 书脊
      dLine(-4, -5, 10, -6, seed + 2, 1.2); dLine(-4, 0, 10, -1, seed + 3, 1.2); // 书名
      hatch(2, 3, 9, 7, seed + 4, 4, 1);
      break;
    }
  }
}

function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

/* ---------- 场景绘制（draw 与菜单背景共用） ---------- */

// 天空渐变（越高越蓝；屏幕空间绘制）
function drawSky(cy) {
  const skyTop = Math.min(1, Math.max(0, -cy / (400 * PARAMS.pxPerMeter)));
  const g = ctx.createLinearGradient(0, 0, 0, LOGIC_H);
  g.addColorStop(0, `rgb(${232 - skyTop * 130}, ${244 - skyTop * 100}, ${248 - skyTop * 40})`);
  g.addColorStop(1, `rgb(${232 - skyTop * 55}, ${244 - skyTop * 40}, ${248 - skyTop * 15})`);
  ctx.fillStyle = g;
  // 多涂一圈余量：视野撑开（缩小）时边缘不露底
  ctx.fillRect(-100, -100, LOGIC_W + 200, LOGIC_H + 200);
}

// 高空氛围：太阳、漂云、星月（垂直视差装饰层，屏幕空间）
function drawCloudsStars(cy, t) {
  const m = -cy / PARAMS.pxPerMeter; // 相机高度（米）

  // 太阳：低空挂着，随爬升缓缓下沉、淡出
  const sunA = clamp(1 - (m - 110) / 70, 0, 1);
  if (sunA > 0) {
    const sx = LOGIC_W - 76, sy = 92 + m * 0.32;
    ctx.save();
    ctx.globalAlpha = sunA * 0.9;
    ctx.fillStyle = 'rgba(255,216,140,0.5)';
    ctx.beginPath(); ctx.arc(sx, sy, 27, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#e2b04a'; ctx.lineWidth = 2;
    dCircle(sx, sy, 17, 12, 2);
    for (let i = 0; i < 8; i++) {
      const a = t * 0.14 + i * Math.PI / 4;
      dLine(sx + Math.cos(a) * 31, sy + Math.sin(a) * 31, sx + Math.cos(a) * 39, sy + Math.sin(a) * 39, 20 + i, 2);
    }
    ctx.restore();
  }

  // 云：视差 0.45，缓慢横漂，偶尔画一张打瞌睡的云脸；高空淡出
  const cloudA = clamp(1 - (m - 210) / 90, 0, 1);
  if (cloudA > 0) {
    const par = 0.45, sp = 300;
    const lo = Math.floor((cy * par - 140) / sp), hi = Math.ceil((cy * par + LOGIC_H + 140) / sp);
    for (let i = lo; i <= hi; i++) {
      const sy = i * sp - cy * par + srand(i * 23.7) * 140;
      if (sy < -70 || sy > LOGIC_H + 70) continue;
      const drift = ((t * (6 + srand(i * 3) * 7) + srand(i * 13) * 900) % (LOGIC_W + 240)) - 120;
      const sc = 0.7 + srand(i * 17) * 0.6;
      ctx.save();
      ctx.translate(drift, sy);
      ctx.scale(sc, sc);
      ctx.globalAlpha = cloudA * (0.55 + srand(i * 5) * 0.3);
      ctx.fillStyle = 'rgba(255,255,255,0.85)';
      ctx.strokeStyle = 'rgba(110,130,155,0.55)'; ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(-32, 7);
      ctx.arc(-19, 2, 13, Math.PI * 0.9, Math.PI * 1.85);
      ctx.arc(1, -7, 16, Math.PI * 1.05, Math.PI * 1.9);
      ctx.arc(21, -1, 12, Math.PI * 1.15, Math.PI * 2.02);
      ctx.lineTo(32, 7);
      ctx.closePath();
      ctx.fill(); ctx.stroke();
      if (srand(i * 31) > 0.6) {
        ctx.strokeStyle = 'rgba(90,105,125,0.6)'; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(-9, -2, 2.6, Math.PI * 0.15, Math.PI * 0.85); ctx.stroke();
        ctx.beginPath(); ctx.arc(6, -2, 2.6, Math.PI * 0.15, Math.PI * 0.85); ctx.stroke();
        ctx.beginPath(); ctx.arc(-1, 3, 3.5, Math.PI * 0.12, Math.PI * 0.8); ctx.stroke();
      }
      ctx.restore();
    }
  }

  // 星星 + 月亮：高空淡入（视差 0.15，几乎固定在屏幕上）
  const starA = clamp((m - 150) / 80, 0, 1);
  if (starA > 0) {
    const par = 0.15, sp = 130;
    const lo = Math.floor((cy * par - 40) / sp), hi = Math.ceil((cy * par + LOGIC_H + 40) / sp);
    for (let i = lo; i <= hi; i++) {
      const sy = i * sp - cy * par;
      const sx = srand(i * 13.7) * LOGIC_W;
      const tw = 0.45 + 0.4 * Math.sin(t * (1 + srand(i) * 1.4) + i * 2.4);
      const r = 1.1 + srand(i * 7) * 1.5;
      ctx.fillStyle = `rgba(255,253,240,${starA * tw})`;
      ctx.beginPath(); ctx.arc(sx, sy, r, 0, Math.PI * 2); ctx.fill();
      if (srand(i * 3) > 0.72) {
        ctx.strokeStyle = `rgba(255,253,240,${starA * tw * 0.7})`; ctx.lineWidth = 1;
        dLine(sx - 4, sy, sx + 4, sy, i, 1);
        dLine(sx, sy - 4, sx, sy + 4, i + 1, 1);
      }
    }
    const moonA = clamp((m - 130) / 60, 0, 1);
    const mx = 64, my = 128 - cy * 0.004;
    ctx.save();
    ctx.globalAlpha = moonA * 0.95;
    ctx.fillStyle = 'rgba(252,248,228,0.95)';
    ctx.beginPath(); ctx.arc(mx, my, 20, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(170,182,200,0.4)';
    ctx.beginPath(); ctx.arc(mx - 6, my - 5, 4, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(mx + 7, my + 6, 2.8, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(150,160,180,0.65)'; ctx.lineWidth = 1.5;
    dCircle(mx, my, 20, 71, 1.5);
    ctx.restore();
  }
}

// 双塔（涂鸦风）：歪线描边 + 随机亮灯的暖黄窗 + 晾衣绳；142m 收顶挂旗，顶上变机房 + 红色警示灯
function drawTowers(cy, t) {
  const step = 60;
  const roofY = -142 * PARAMS.pxPerMeter; // 光华楼顶
  ctx.strokeStyle = '#4a5568';
  for (let wy = Math.floor(cy / step) * step; wy < cy + LOGIC_H + step; wy += step) {
    const cc = canyonCenterAt(wy), half = canyonHalfAt(wy);
    const above = wy + step <= roofY; // 整行高出楼顶
    ctx.fillStyle = above ? 'rgba(158,168,184,0.45)' : 'rgba(196,205,214,0.5)';
    const lx = cc - half - PARAMS.towerLeftW - 12, rx = cc + half;
    ctx.fillRect(lx, wy, PARAMS.towerLeftW + 12, step + 1);
    ctx.fillRect(rx, wy, PARAMS.towerRightW + 12, step + 1);
    const rowSeed = Math.round(wy / step) * 13;
    dLine(lx, wy, lx, wy + step, rowSeed, 2.5);          // 左塔内缘
    dLine(rx, wy, rx, wy + step, rowSeed + 1, 2.5);      // 右塔内缘
    // 手绘歪窗户（打勾的方形），部分亮着暖黄的灯
    for (let i = 0; i < 2; i++) {
      const wx1 = lx + 12 + i * 26, wx2 = rx + 16 + i * 26;
      if (!above) {
        if (srand((rowSeed + 40 + i) * 3.7) > 0.72) { ctx.fillStyle = 'rgba(255,208,112,0.85)'; ctx.fillRect(wx1 + 1, wy + 17, 10, 14); }
        if (srand((rowSeed + 60 + i) * 5.3) > 0.72) { ctx.fillStyle = 'rgba(255,208,112,0.85)'; ctx.fillRect(wx2 + 1, wy + 17, 10, 14); }
      }
      dRect(wx1, wy + 16, 12, 16, rowSeed + 40 + i, 1.5);
      dRect(wx2, wy + 16, 12, 16, rowSeed + 60 + i, 1.5);
      hatch(wx1 + 1, wy + 17, 10, 14, rowSeed + 80 + i, 5, 1);
      hatch(wx2 + 1, wy + 17, 10, 14, rowSeed + 90 + i, 5, 1);
    }
    // 塔外侧排线阴影（左塔左缘、右塔右缘）
    hatch(lx + 1, wy, 14, step, rowSeed + 100, 9, 1);
    hatch(rx + PARAMS.towerRightW + 12 - 15, wy, 14, step, rowSeed + 110, 9, 1);
    // 低层偶尔拉一根晾衣绳（挂两件小衣服）
    if (!above && srand(rowSeed * 1.7) > 0.86) {
      ctx.strokeStyle = 'rgba(74,85,104,0.7)'; ctx.lineWidth = 1;
      dLine(lx + 8, wy + 8, lx + 76, wy + 13, rowSeed + 200, 1);
      ctx.fillStyle = 'rgba(228,120,92,0.75)'; ctx.fillRect(lx + 20, wy + 9, 6, 8);
      ctx.fillStyle = 'rgba(96,142,192,0.75)'; ctx.fillRect(lx + 40, wy + 11, 6, 8);
      ctx.strokeStyle = '#4a5568';
    }
    // 楼顶以上：红色航空警示灯（慢闪）
    if (above && Math.round(wy / step) % 2 === 0) {
      const blink = 0.3 + 0.5 * (Math.sin(t * 5 + wy * 0.01) * 0.5 + 0.5);
      ctx.fillStyle = `rgba(232,80,60,${blink})`;
      ctx.beginPath(); ctx.arc(lx + 6, wy + 10, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rx + PARAMS.towerRightW + 6, wy + 10, 3, 0, Math.PI * 2); ctx.fill();
    }
    // 光华楼收顶：双线檐口 + 右塔旗杆飘旗（只画跨越 roofY 的那一行）
    if (wy < roofY && wy + step > roofY) {
      dLine(lx - 5, roofY, lx + PARAMS.towerLeftW + 17, roofY, 501, 3);
      dLine(lx - 5, roofY + 7, lx + PARAMS.towerLeftW + 17, roofY + 7, 502, 2);
      dLine(rx - 5, roofY, rx + PARAMS.towerRightW + 17, roofY, 503, 3);
      dLine(rx - 5, roofY + 7, rx + PARAMS.towerRightW + 17, roofY + 7, 504, 2);
      const fx = rx + 34;
      dLine(fx, roofY, fx, roofY - 36, 505, 2);
      const wave = Math.sin(t * 3.2) * 3;
      ctx.fillStyle = '#2e6da4';
      ctx.beginPath();
      ctx.moveTo(fx, roofY - 36); ctx.lineTo(fx + 24, roofY - 29 + wave); ctx.lineTo(fx, roofY - 21);
      ctx.closePath(); ctx.fill();
    }
  }
}

// 地面（涂鸦草坪 + 小花 + 「光华风洞」路牌）
function drawGround() {
  ctx.fillStyle = '#a8d18d';
  // 草坪多涂一圈余量：视野撑开时画面底缘不露底
  ctx.fillRect(0, 0, LOGIC_W, 560);
  ctx.strokeStyle = '#4f8a3d'; ctx.lineWidth = 3;
  dLine(0, 0, LOGIC_W, 0, 999, 3);
  ctx.strokeStyle = '#5f9e4a'; ctx.lineWidth = 1.5;
  for (let gx = 10; gx < LOGIC_W; gx += 24) {
    const gy = -2 - srand(gx) * 3;
    dLine(gx, gy, gx - 3, gy - 8, gx * 3, 1.5);
    dLine(gx, gy, gx + 4, gy - 7, gx * 3 + 1, 1.5);
  }
  for (let gx = 40; gx < LOGIC_W; gx += 90) {
    if (srand(gx * 7.3) > 0.4) {
      const fx = gx + srand(gx * 3.1) * 34, fy = -4 - srand(gx) * 4;
      ctx.strokeStyle = '#4f8a3d'; ctx.lineWidth = 1.2;
      dLine(fx, fy, fx, fy - 8, gx, 1.2);
      ctx.fillStyle = srand(gx * 11.7) > 0.5 ? 'rgba(233,120,110,0.95)' : 'rgba(242,202,90,0.95)';
      ctx.beginPath(); ctx.arc(fx, fy - 10, 2.8, 0, Math.PI * 2); ctx.fill();
    }
  }
  ctx.strokeStyle = '#6b5236'; ctx.lineWidth = 2;
  dLine(58, -4, 58, -36, 900, 2);
  ctx.fillStyle = '#f7f1e3'; ctx.fillRect(28, -56, 70, 22);
  dRect(28, -56, 70, 22, 901, 1.5);
  ctx.fillStyle = '#5b4636'; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
  ctx.fillText('光华风洞', 63, -41);
}

// 风柱（纯气流画法）：无框无块，只有向上流动的手绘流线 + 闸口气旋口；顺风期转金
function drawWindColumn(cx, cyy, seed, active, t, buffed) {
  ctx.globalAlpha = active ? 1 : 0.25; // 滑翔期风洞熄灭（视觉变暗）
  const cw = PARAMS.columnWidth / 2;
  const top = cyy + 30, bot = cyy + 160, h = bot - top;
  const cCore = PARAMS.columnCore / 2;

  // 极淡柔光底：只提示气流范围，无任何描边
  const gBody = ctx.createLinearGradient(0, bot, 0, top);
  gBody.addColorStop(0, 'rgba(150,215,170,0)');
  gBody.addColorStop(0.75, 'rgba(150,215,170,0.10)');
  gBody.addColorStop(1, 'rgba(150,215,170,0.22)');
  ctx.fillStyle = gBody;
  ctx.fillRect(cx - cw, top, cw * 2, h);

  // 闸口气旋柔光（升力闸口 = 这股风喷出的口）
  const glowR = cw * (buffed ? 1.15 : 1.0);
  const gc = buffed ? '255,214,130' : '170,230,195';
  const gGate = ctx.createRadialGradient(cx, top, 3, cx, top, glowR);
  gGate.addColorStop(0, `rgba(${gc},${buffed ? 0.36 : 0.24})`);
  gGate.addColorStop(1, `rgba(${gc},0)`);
  ctx.fillStyle = gGate;
  ctx.save();
  ctx.translate(cx, top);
  ctx.scale(1, 0.32);
  ctx.beginPath(); ctx.arc(0, 0, glowR, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  // 上升流线 ×4：正弦波向上流动，下端渐隐、近闸口最亮；核心区内两条更亮更粗
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  for (let i = 0; i < 4; i++) {
    const lx = cx + (i - 1.5) * (cw * 0.42);
    const isCore = Math.abs(lx - cx) < cCore;
    const amp = 3.5 + srand(seed + i * 7) * 3;
    const spd = 2.2 + srand(seed + i * 13) * 1.4;
    const off = srand(seed + i * 3) * 40;
    const grad = ctx.createLinearGradient(0, bot, 0, top);
    if (buffed) {
      grad.addColorStop(0, 'rgba(230,180,60,0)');
      grad.addColorStop(1, `rgba(230,180,60,${isCore ? 0.65 : 0.42})`);
    } else {
      grad.addColorStop(0, 'rgba(60,170,115,0)');
      grad.addColorStop(1, `rgba(24,132,84,${isCore ? 0.6 : 0.36})`);
    }
    ctx.strokeStyle = grad;
    ctx.lineWidth = isCore ? 2.4 : 1.6;
    ctx.beginPath();
    for (let k = 0; k <= 8; k++) {
      const yy = bot - (h * k) / 8;
      const wob = Math.sin(yy * 0.05 - t * spd + off) * amp;
      if (k === 0) ctx.moveTo(lx + wob, yy); else ctx.lineTo(lx + wob, yy);
    }
    ctx.stroke();
    // 流线顶端的小侧勾：顺着线头轻轻一带（不要圆头，避免“伞盖”感）
    const cDir = srand(seed + i * 5) > 0.5 ? 1 : -1;
    ctx.lineWidth = isCore ? 1.7 : 1.2;
    ctx.strokeStyle = buffed ? 'rgba(230,180,60,0.45)' : 'rgba(24,132,84,0.45)';
    ctx.beginPath();
    ctx.arc(lx + cDir * 2.5, top + 0.5, 2.5, cDir > 0 ? -1.1 : Math.PI - 1.1, cDir > 0 ? 0.8 : Math.PI + 0.8);
    ctx.stroke();
  }

  // 核心内：干净的上升雪佛龙（引导钻缝，入柱前渐显、过缝口渐隐）
  ctx.lineWidth = 2.2;
  for (let i = 0; i < 2; i++) {
    const span = h + 50;
    const yy = bot + 25 - ((t * 210 + i * span / 2 + srand(seed) * span) % span);
    const k = (bot + 25 - yy) / span;
    const jx = (srand(seed + i * 11) - 0.5) * 5;
    ctx.strokeStyle = buffed
      ? `rgba(196,138,24,${0.9 * Math.min(1, k / 0.15) * (1 - k * 0.8)})`
      : `rgba(16,122,76,${0.9 * Math.min(1, k / 0.15) * (1 - k * 0.8)})`;
    ctx.beginPath();
    ctx.moveTo(cx - 7 + jx, yy + 6); ctx.lineTo(cx + jx, yy); ctx.lineTo(cx + 7 + jx, yy + 6);
    ctx.stroke();
  }
  ctx.lineCap = 'butt'; ctx.lineJoin = 'miter';
  ctx.globalAlpha = 1;
}

// 校徽球（贴图/手绘兜底 + 一圈淡光晕垫底，高空淡蓝天下保持辨识度）；在当前原点绘制
function drawBallLogoAt(r) {
  const halo = ctx.createRadialGradient(0, 0, r * 0.5, 0, 0, r * 2.2);
  halo.addColorStop(0, 'rgba(255,255,255,0.45)');
  halo.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = halo;
  ctx.beginPath(); ctx.arc(0, 0, r * 2.2, 0, Math.PI * 2); ctx.fill();
  if (fudanImgReady) {
    ctx.save();
    ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.clip();
    ctx.drawImage(fudanImg, -r, -r, r * 2, r * 2);
    ctx.restore();
    ctx.strokeStyle = '#0b3a73';
    dCircle(0, 0, r + 1, 4248, 1.5);
  } else {
    ctx.fillStyle = '#0f4c95';
    ctx.beginPath(); ctx.arc(0, 0, r + 1, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#fffbe8';
    dCircle(0, 0, r - 1, 4242, 1.5);
    dCircle(0, 0, r - 4.5, 4243, 1);
    ctx.fillStyle = '#fffbe8'; ctx.textAlign = 'center';
    ctx.font = 'bold 10px serif';
    ctx.fillText('复旦', 0, -1);
    ctx.strokeStyle = '#fffbe8'; ctx.lineWidth = 1.2;
    dLine(-6, 4, 0, 7, 4244, 1.2); dLine(0, 7, 6, 4, 4245, 1.2);
    dLine(-6, 6, 0, 9, 4246, 1); dLine(0, 9, 6, 6, 4247, 1);
    ctx.strokeStyle = '#0b3a73';
    dCircle(0, 0, r + 1, 4248, 1.5);
  }
}

// 手绘小风旋（菜单标题两侧的装饰）
function drawSwirl(x, y, dir, t) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(dir, 1);
  ctx.strokeStyle = 'rgba(184,168,144,0.9)'; ctx.lineWidth = 2;
  const w = Math.sin(t * 2 + x) * 1.5;
  ctx.beginPath(); ctx.arc(0, 0, 11, -2.4, 0.7); ctx.stroke();
  ctx.beginPath(); ctx.arc(4, -2, 6.5, -2.8, 1.0); ctx.stroke();
  dLine(12, 4 + w, 26, 2 + w, 31, 2);
  ctx.restore();
}

// —— 渲染 ——
function draw() {
  ctx.clearRect(0, 0, LOGIC_W, LOGIC_H);

  if (state === 'menu') { drawMenu(); return; }

  const t = nowT();
  ctx.save();
  // 受击屏幕震动（整屏轻微抖动，幅度随剩余时间衰减）
  if (shakeT > 0) {
    const k = shakeT / 0.25, sSeed = Math.floor(t * 60);
    ctx.translate((srand(sSeed) - 0.5) * 2 * shakeAmp * k, (srand(sSeed + 7) - 0.5) * 2 * shakeAmp * k);
  }
  // 相机缩放：高速时视野变广（加速感），吃柱瞬间前冲一下
  if (zoomCur !== 1) {
    ctx.translate(LOGIC_W / 2, LOGIC_H * 0.45);
    ctx.scale(zoomCur, zoomCur);
    ctx.translate(-LOGIC_W / 2, -LOGIC_H * 0.45);
  }
  // 天空与氛围层（屏幕空间：太阳/云/星月自带视差）
  drawSky(camY);
  drawCloudsStars(camY, t);
  ctx.translate(0, -camY);

  drawTowers(camY, t);
  drawGround();

  // 风柱
  for (const c of columns) {
    if (c.y < camY - 60 || c.y > camY + LOGIC_H + 60) continue;
    drawWindColumn(c.x, c.y, Math.round(c.y) * 3 + Math.round(c.x), gustPhase === 'gust' || PARAMS.calmColumns, gameT, combo >= PARAMS.comboBuffAt);
  }

  // 风粒子
  ctx.strokeStyle = 'rgba(255,255,255,0.8)'; ctx.lineWidth = 2;
  for (const p of particles) {
    ctx.globalAlpha = Math.min(1, p.life);
    ctx.strokeStyle = p.gold ? 'rgba(230,170,40,0.9)' : p.green ? 'rgba(46,158,107,0.9)' : 'rgba(255,255,255,0.8)';
    ctx.lineWidth = (p.green || p.gold) ? 3 : 2;
    ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y + (p.green ? -22 : 16)); ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // 杂物：本体带渐隐拖尾（拖尾方向即运动方向）
  for (const d of debrisList) {
    // 拖尾：由远及近的一串渐大渐浓的圆点
    for (let i = 0; i < d.trail.length; i++) {
      const p = d.trail[i], k = i / d.trail.length; // 0=尾端 1=靠近本体
      ctx.fillStyle = `rgba(120,130,145,${0.06 + k * 0.22})`;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 2 + k * 8, 0, Math.PI * 2);
      ctx.fill();
    }
    // 本体（手绘涂鸦）
    ctx.save();
    ctx.translate(d.x, d.y);
    ctx.rotate(d.rot);
    drawDebrisDoodle(d.kind, d.seed);
    ctx.restore();
  }

  // 小球（涂鸦风：不闭合歪圆 + 手写 FUDAN + 冲刺速度线）
  ctx.save();
  ctx.translate(ball.x, ball.y);
  // 倾斜 = 横向速度感 + 横向加速度感（被风推/被撞/顶风时都会压向一侧）
  const tilt = clamp(ball.vx / PARAMS.maxVx, -1, 1) * 0.45
             + clamp((ball.ax || 0) / PARAMS.inputAccel, -1, 1) * 0.3
             + (ball.gusting ? 0 : Math.sin(gameT * 2.6) * 0.1); // 滑翔期的纸片漂浮感
  ctx.rotate(clamp(tilt, -0.9, 0.9));
  // 球体加速反馈：高速拉伸（平滑速度驱动）+ 身后速度线（柱内绿/顺风金，柱外高速白）
  const sv = Math.max(0, -(ball.svy ?? ball.vy));
  const ballBuffed = combo >= PARAMS.comboBuffAt;
  if (sv > 350) {
    const stretch = 1 + Math.min(0.6, sv / PARAMS.columnMaxVy * 0.6);
    ctx.scale(1 / Math.sqrt(stretch), stretch);
  }
  if (ball.inColumn || sv > 1100) {
    ctx.strokeStyle = (ballBuffed || superT > 0) && ball.inColumn ? 'rgba(226,168,40,0.85)'
      : ball.inColumn ? (ball.inCore ? 'rgba(46,158,107,0.75)' : 'rgba(46,158,107,0.4)')
      : 'rgba(255,255,255,0.45)';
    for (let i = 0; i < 4; i++) { // 身后拖出的速度线
      const sx = (i - 1.5) * 9 + (srand(i + 7) - 0.5) * 4;
      const len = 24 + srand(i) * 26 + Math.min(40, sv / 40);
      dLine(sx, ball.r + 4, sx + (srand(i + 3) - 0.5) * 5, ball.r + 4 + len, i * 17 + 5, 2);
    }
  }
  drawBallLogoAt(ball.r); // 校徽球（贴图/手绘兜底 + 淡光晕垫底）
  if (ball.hitFlash > 0) { // 被砸红闪
    ctx.strokeStyle = `rgba(231,76,60,${ball.hitFlash / 0.3})`; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(0, 0, ball.r + 5, 0, Math.PI * 2); ctx.stroke();
  }
  if (hurtT > 0) { // 带伤状态：校徽变红并闪烁，警示“再挨一下就出局”
    const blink = 0.45 + 0.4 * Math.sin(nowT() * 18);
    ctx.fillStyle = `rgba(220,60,50,${(blink * 0.5).toFixed(3)})`;
    ctx.beginPath(); ctx.arc(0, 0, ball.r + 1, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = `rgba(220,60,50,${blink.toFixed(3)})`;
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(0, 0, ball.r + 6, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.restore();

  ctx.restore();

  drawHUD();

  if (state === 'over') drawOver();
}

function drawHUD() {
  // 米数（白边描字，任何背景都可读）
  ctx.textAlign = 'center';
  ctx.font = 'bold 34px sans-serif';
  ctx.strokeStyle = 'rgba(255,255,255,0.75)'; ctx.lineWidth = 6; ctx.lineJoin = 'round';
  ctx.strokeText(maxMeters + ' m', LOGIC_W / 2, 54);
  ctx.fillStyle = '#234';
  ctx.fillText(maxMeters + ' m', LOGIC_W / 2, 54);
  ctx.font = '14px sans-serif';
  ctx.strokeStyle = 'rgba(255,255,255,0.6)'; ctx.lineWidth = 3;
  ctx.strokeText(landmark(maxMeters), LOGIC_W / 2, 76);
  ctx.fillText(landmark(maxMeters), LOGIC_W / 2, 76);

  // 风力预告条（手绘小盒：圆头墨条 + 刻度 + 左端小风旋）
  const barW = 200, barH = 8, bx = (LOGIC_W - barW) / 2, by = 90 + 24;
  const phase = gustPhase === 'gust' ? PARAMS.gustDur : PARAMS.calmDur;
  const prog = 1 - gustT / phase;
  const fillW = barW * (gustPhase === 'gust' ? 1 - prog : prog);
  ctx.lineCap = 'round';
  ctx.strokeStyle = 'rgba(255,255,255,0.65)'; ctx.lineWidth = barH;
  ctx.beginPath(); ctx.moveTo(bx + 5, by + barH / 2); ctx.lineTo(bx + barW - 5, by + barH / 2); ctx.stroke();
  ctx.strokeStyle = gustPhase === 'gust' ? '#3498db' : '#b9b0a0';
  if (fillW > 7) {
    ctx.beginPath(); ctx.moveTo(bx + 5, by + barH / 2); ctx.lineTo(bx + 5 + fillW - 7, by + barH / 2); ctx.stroke();
  }
  ctx.lineCap = 'butt';
  ctx.strokeStyle = 'rgba(74,85,104,0.4)'; ctx.lineWidth = 1.2;
  for (const tk of [bx + barW / 3, bx + barW * 2 / 3]) {
    ctx.beginPath(); ctx.moveTo(tk, by - 1); ctx.lineTo(tk, by + barH + 1); ctx.stroke();
  }
  ctx.strokeStyle = '#4a5568';
  dRect(bx - 3, by - 3, barW + 6, barH + 6, 33, 1.5);
  const swx = bx - 17, swy = by + barH / 2 + 1;
  ctx.strokeStyle = gustPhase === 'gust' ? '#3498db' : '#a89a84'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(swx, swy, 7, -0.5, 3.4); ctx.stroke();
  ctx.beginPath(); ctx.arc(swx + 2, swy, 3.4, 1.4, 4.4); ctx.stroke();
  dLine(swx - 13, swy + 4, swx - 5, swy + 5, 55, 1.5);

  // 超级加速剩余时间（金色小条，无文字）
  if (superT > 0) {
    const sw2 = 120, sx2 = (LOGIC_W - sw2) / 2, sy2 = by + 15;
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(230,180,60,0.9)'; ctx.lineWidth = 5;
    ctx.beginPath(); ctx.moveTo(sx2 + 3, sy2); ctx.lineTo(sx2 + 3 + Math.max(4, (superT / PARAMS.superDur) * (sw2 - 6)), sy2); ctx.stroke();
    ctx.lineCap = 'butt';
  }

  // 涡流预警与生效：警示带打在风吹来的那一侧
  if (vortex) {
    const warning = vortex.t < vortex.warn; // 预警阶段
    const bandW = 90;
    const srcX = vortex.dir > 0 ? 0 : LOGIC_W - bandW; // 风从哪侧来
    if (warning) {
      // 预警：来风侧脉冲红色渐变带 + 指向箭头
      const pulse = 0.35 + 0.25 * Math.sin(gameT * 18);
      const grad = vortex.dir > 0
        ? ctx.createLinearGradient(0, 0, bandW, 0)
        : ctx.createLinearGradient(LOGIC_W, 0, LOGIC_W - bandW, 0);
      grad.addColorStop(0, `rgba(231,76,60,${pulse})`);
      grad.addColorStop(1, 'rgba(231,76,60,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(srcX, 0, bandW, LOGIC_H);
      // 箭头链（指向推动方向），上下两处
      ctx.fillStyle = `rgba(231,76,60,${0.5 + 0.4 * Math.sin(gameT * 18)})`;
      ctx.font = 'bold 30px sans-serif';
      const ax = vortex.dir > 0 ? bandW * 0.55 : LOGIC_W - bandW * 0.55;
      ctx.fillText(vortex.dir > 0 ? '▶' : '◀', ax, LOGIC_H * 0.3);
      ctx.fillText(vortex.dir > 0 ? '▶' : '◀', ax, LOGIC_H * 0.65);
    } else {
      // 生效期：全屏横向流动风线（方向=推动方向），来风侧保留淡红
      ctx.fillStyle = 'rgba(231,76,60,0.10)';
      ctx.fillRect(srcX, 0, bandW, LOGIC_H);
      ctx.strokeStyle = 'rgba(231,76,60,0.4)'; ctx.lineWidth = 2;
      for (let i = 0; i < 7; i++) {
        const ly = (i * 137 + (gameT * 260) % LOGIC_H) % LOGIC_H; // 线条随时间下移循环
        const lx = (i * 97 + (gameT * vortex.dir * 620)) % (LOGIC_W + 120) - 60;
        ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(lx + vortex.dir * 46, ly); ctx.stroke();
      }
    }
  }

  // 静音按钮（右上角小喇叭；点击或按 M 切换）
  ctx.save();
  ctx.translate(LOGIC_W - 22, 24);
  const mic = muted ? 'rgba(120,110,100,0.55)' : 'rgba(90,80,70,0.75)';
  ctx.strokeStyle = mic; ctx.fillStyle = mic; ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(-7, -3); ctx.lineTo(-3, -3); ctx.lineTo(2, -7); ctx.lineTo(2, 7); ctx.lineTo(-3, 3); ctx.lineTo(-7, 3);
  ctx.closePath(); ctx.fill();
  if (muted) {
    ctx.beginPath(); ctx.moveTo(5, -6); ctx.lineTo(10, 6); ctx.stroke();
  } else {
    ctx.beginPath(); ctx.arc(3, 0, 5, -0.9, 0.9); ctx.stroke();
    ctx.beginPath(); ctx.arc(3, 0, 8, -0.9, 0.9); ctx.stroke();
  }
  ctx.restore();
}

function drawMenu() {
  const t = nowT();
  const menuCam = -520;
  // 背景 = 真实的游戏世界（双塔 + 草坪 + 两根喷着气流的风柱 + 漂浮的校徽球）
  drawSky(menuCam);
  drawCloudsStars(menuCam, t);
  ctx.save();
  ctx.translate(0, -menuCam);
  drawTowers(menuCam, t);
  drawGround();
  drawWindColumn(96, -330, 777, true, t, false);
  drawWindColumn(312, -160, 778, true, t, false);
  ctx.save();
  ctx.translate(LOGIC_W * 0.62, -400 + Math.sin(t * 1.5) * 9);
  ctx.rotate(Math.sin(t * 0.9) * 0.12);
  drawBallLogoAt(16);
  ctx.restore();
  ctx.restore();

  // 半透明牛皮纸蒙层 + 笔记本横线
  ctx.fillStyle = 'rgba(247,241,227,0.85)';
  ctx.fillRect(0, 0, LOGIC_W, LOGIC_H);
  ctx.strokeStyle = 'rgba(150,130,100,0.09)'; ctx.lineWidth = 1;
  for (let ry = 64; ry < LOGIC_H; ry += 48) {
    ctx.beginPath(); ctx.moveTo(0, ry); ctx.lineTo(LOGIC_W, ry); ctx.stroke();
  }

  ctx.textAlign = 'center';
  // 标题 + 手绘下划线 + 两侧小风旋
  ctx.fillStyle = '#2d3748'; ctx.font = 'bold 36px "Segoe Print","Comic Sans MS",sans-serif';
  ctx.fillText('光华风洞·乘风者', LOGIC_W / 2, 230);
  ctx.strokeStyle = '#e67e22';
  dLine(LOGIC_W / 2 - 150, 248, LOGIC_W / 2 + 150, 244, 77, 3);
  drawSwirl(88, 264, 1, t);
  drawSwirl(LOGIC_W - 88, 264, -1, t);

  ctx.font = '17px sans-serif'; ctx.fillStyle = '#5b4636';
  ctx.fillText('按住屏幕左右半边（或 ←→ 键）横移', LOGIC_W / 2, 320);
  ctx.fillText('上升全靠吃风柱：钻进窄缝中心升力翻倍', LOGIC_W / 2, 348);
  ctx.fillText('别撞楼、别被杂物砸中、别掉下去', LOGIC_W / 2, 376);

  // 开始按钮：手绘圈带“沸腾线”抖动 + 呼吸脉冲
  const pulse = 1 + Math.sin(t * 2.6) * 0.035;
  ctx.save();
  ctx.translate(LOGIC_W / 2, 453);
  ctx.scale(pulse, pulse);
  ctx.fillStyle = '#e67e22'; ctx.font = 'bold 22px "Segoe Print","Comic Sans MS",sans-serif';
  ctx.fillText('点击 / 空格 开始', 0, 7);
  ctx.strokeStyle = '#e67e22';
  dCircle(0, -3, 110, 88 + (Math.floor(t * 2) % 4), 2.5);
  ctx.restore();

  if (bestMeters > 0) {
    ctx.fillStyle = '#5b4636'; ctx.font = '15px sans-serif';
    ctx.fillText('最高纪录：' + bestMeters + ' m', LOGIC_W / 2, 596);
    // 小三角旗（随风轻摆）
    ctx.strokeStyle = '#8a7a5c'; ctx.lineWidth = 1.5;
    dLine(LOGIC_W / 2 - 96, 590, LOGIC_W / 2 - 96, 572, 61, 1.5);
    ctx.fillStyle = '#e67e22';
    ctx.beginPath();
    ctx.moveTo(LOGIC_W / 2 - 96, 572);
    ctx.lineTo(LOGIC_W / 2 - 81, 576 + Math.sin(t * 2.5) * 1.5);
    ctx.lineTo(LOGIC_W / 2 - 96, 580);
    ctx.closePath(); ctx.fill();
  }
}

function drawOver() {
  ctx.fillStyle = 'rgba(90,70,40,0.55)'; // 牛皮纸暗化
  ctx.fillRect(0, 0, LOGIC_W, LOGIC_H);
  // 成绩便签（歪斜的纸片）
  ctx.save();
  ctx.translate(LOGIC_W / 2, 300);
  ctx.rotate(-0.03);
  ctx.fillStyle = '#f7f1e3';
  ctx.fillRect(-155, -165, 310, 330);
  ctx.strokeStyle = '#8a7a5c';
  dRect(-155, -165, 310, 330, 55, 2.5);
  // 两角的手绘胶带（歪着贴的半透明纸带）
  ctx.save();
  ctx.translate(-140, -152); ctx.rotate(0.38);
  ctx.fillStyle = 'rgba(226,212,170,0.75)';
  ctx.fillRect(-38, -11, 76, 22);
  ctx.restore();
  ctx.save();
  ctx.translate(140, -152); ctx.rotate(-0.38);
  ctx.fillStyle = 'rgba(226,212,170,0.75)';
  ctx.fillRect(-38, -11, 76, 22);
  ctx.restore();
  ctx.textAlign = 'center';
  ctx.fillStyle = '#8a3033'; ctx.font = 'bold 24px sans-serif';
  ctx.fillText(deathReason, 0, -110);
  ctx.fillStyle = '#2d3748'; ctx.font = 'bold 54px "Segoe Print","Comic Sans MS",sans-serif';
  ctx.fillText(maxMeters + ' m', 0, -30);
  ctx.strokeStyle = '#e67e22';
  dLine(-100, -14, 100, -18, 66, 3);
  ctx.fillStyle = '#5b4636'; ctx.font = '18px sans-serif';
  ctx.fillText(titleOf(maxMeters), 0, 30);
  ctx.fillText(landmark(maxMeters), 0, 60);
  ctx.fillStyle = '#b8860b'; ctx.font = '15px sans-serif';
  ctx.fillText('最高纪录：' + bestMeters + ' m' + (maxMeters >= bestMeters ? ' 🎉新纪录!' : ''), 0, 100);
  // 新纪录：便签四周闪手绘小星光
  if (maxMeters >= bestMeters && bestMeters > 0) {
    const t2 = nowT();
    for (let i = 0; i < 8; i++) {
      const sx2 = -178 + srand(i * 9.3) * 356, sy2 = -195 + srand(i * 4.7) * 390;
      const tw2 = 0.5 + 0.5 * Math.sin(t2 * 3 + i * 1.7);
      ctx.strokeStyle = `rgba(200,150,30,${0.35 + tw2 * 0.55})`;
      ctx.lineWidth = 2;
      dLine(sx2 - 5, sy2, sx2 + 5, sy2, i * 3, 2);
      dLine(sx2, sy2 - 5, sx2, sy2 + 5, i * 3 + 1, 2);
    }
  }
  ctx.fillStyle = '#2d3748'; ctx.font = 'bold 20px "Segoe Print","Comic Sans MS",sans-serif';
  ctx.fillText('点击 / 空格 再来一次', 0, 145);
  ctx.restore();
}

// —— 主循环 ——
let lastT = performance.now();
function loop(now) {
  const dt = Math.min(0.033, (now - lastT) / 1000);
  lastT = now;
  update(dt);
  draw();
  if ((state === 'menu' || state === 'over') && windGain && audio) {
    windGain.gain.setTargetAtTime(0.0001, audio.currentTime, 0.4); // 非对局时风声淡出
  }
  requestAnimationFrame(loop);
}
reset();
requestAnimationFrame(loop);
